query.sparql:
PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?uri WHERE { res:Salt_Lake_City dbp:timeZone?uri }

PREFIX dct: <http://purl.org/dc/terms/>
PREFIX dbc: <http://dbpedia.org/resource/Category:]
SELECT DISTINCT?uri WHERE {?uri dct:subject dbc:Assassins_of_Julius_Caesar }

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX onto: <http://dbpedia.org/ontology/>
SELECT?uri WHERE {
 ?uri rdf:type onto:Mountain ; 
          onto:location?location.
 ?location rdfs:label "Germany"@en.
 ?uri onto:elevation?elevation.
  FILTER (?elevation = (SELECT max(?elevation2) {?uri2 rdf:type onto:Mountain ; 
          onto:location?location2.
         ?location2 rdfs:label "Germany"@en.
         ?uri2 onto:elevation?elevation2 }))
}

PREFIX dbpedia2: <http://dbpedia.org/property/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT?string WHERE { res:Frank_Herbert dbpedia2:birthplace?string }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT?capacity WHERE {
  { dbr:Estádio_dos_Barbosas dbo:ground dbr:FC_Porto. dbr:Estádio_dos_Barbosas dbo:capacity?capacity }
}

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?string WHERE { res:Angela_Merkel dbp:birthDate?string }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT?uri WHERE { res:Berlin dbo:mayor?uri }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT?country
WHERE {
  { dbr:Bill_Gates dbo:birthPlace?birthPlace.
   ?birthPlace dbo:location?country.
    FILTER (?country dbr:United_States) }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT DISTINCT?uri
WHERE {
 ?uri dbo:occupation "Skateboarding".
 ?uri dbo:birthPlace dbr:Sweden
}
UNION
{
 ?uri dbo:birthPlace?place.
 ?place dbo:country dbr:Sweden
}

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?String WHERE { res:Millipede rdfs:label?String }

PREFIX dbpedia: <http://dbpedia.org/resource/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
SELECT DISTINCT?string WHERE { dbpedia:Forbes foaf:homepage?string }

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT DISTINCT?uri WHERE { res:Meindert_Hobbema dbo:publisher?uri }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT?uri WHERE { res:K2 dbo:highest?uri }

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?date WHERE { res:Finland dbp:membership_date?date }

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
SELECT?nm WHERE { dbr:Baghdad rdfs:label?nm. FILTER (lang(?nm) = "en") }

SELECT?uri WHERE {
 ?uri <http://dbpedia.org/ontology/country> <http://dbpedia.org/resource/United_States>.
 ?uri <http://dbpedia.org/ontology/populationDensity>?density.
  FILTER (?density = (SELECT MAX(?d) {?uri <http://dbpedia.org/ontology/populationDensity>?d } ) )
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT?string WHERE { res:Berlin dbo:postalCode?string. FILTER (lang(?string) = "en") }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT DISTINCT?uri
WHERE {
  {?uri dbo:occupation res:Surfer ; dbo:birthPlace dbr:Australia}
  UNION
  {?uri dbo:occupation res:Surfer ; dbo:birthPlace?place.
  ?place dbo:location dbr:Australia}}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT?uri WHERE { res:Sean_Parnell dbo:birthPlace?uri FILTER (?uri!= <http://dbpedia.org/resource/Alaska>) }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX res: <http://dbpedia.org/resource/>
SELECT?years WHERE {
  res:Ford_Model_T dbo:productionStartYear?start;
  dbo:productionEndYear?end.
  BIND (xsd:integer(?end -?start) AS?years) }

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT xsd:date(?date) WHERE { res:Carlo_Giuliani dbp:deathDate?date }

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX onto: <http://dbpedia.org/ontology/>
SELECT?uri?string WHERE { dbr:Abraham_Lincoln onto:spouse?uri }

PREFIX dbpedia-owl: <http://dbpedia.org/ontology/>
SELECT (COUNT(?award) AS?Counter)
WHERE { 
  dbr:Bertrand_Russell dbpedia-owl:awarded?award.
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbc: <http://dbpedia.org/resource/Category:]
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT?s
WHERE {
 ?s dct:subject dbc:Missions_to_the_Sun ;
    rdf:type dbo:Spacecraft.
}

PREFIX res: <http://dbpedia.org/resource/>
PREFIX onto: <http://dbpedia.org/ontology/>
SELECT?number WHERE { res:IBM dbo:revenue?number }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT?uri WHERE {?uri rdfs:label?label. FILTER (str(?label) = "Tom Hanks") }

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?uri WHERE { res:Yenisei_River dbp:flowsThrough?uri }

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT DISTINCT?uri WHERE {?uri a dbo:Female?chancellor.?chancellor res:Chancellor_of_Germany. }

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?uri WHERE { res:Aldi dbp:founder?uri }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT DISTINCT?uri
WHERE {
 ?uri a dbo:Company ;
        dbo:industry dbr:Aerospace ;
        dbo:industry dbr:Medical.
}

PREFIX dct: <http://purl.org/dc/terms/>
PREFIX dbc: <http://dbpedia.org/resource/Category:>
ASK WHERE {?uri dct:subject dbc:Castles_in_the_United_States }

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT DISTINCT?uri
WHERE {
  { <http://dbpedia.org/resource/Rhine> dbo:locatedIn?uri }
  UNION
  {?uri dbo:location <http://dbpedia.org/resource/Rhine> } }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT * WHERE { res:Elizabeth_II dbo:father?uri.?uri <http://xmlns.com/foaf/0.1/gender> "male"@en }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT?n WHERE {?n dbo:wavelength "430-450"^^xsd:string }

PREFIX dbpedia-owl: <http://dbpedia.org/ontology/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
SELECT DISTINCT?s WHERE { <http://dbpedia.org/resource/Teenage_Mutant_Ninja_Turtles> dbpedia-owl:member?x.?x foaf:givenName?s }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT xsd:date(?birthDate) WHERE { res:Jack_Wolfskin dbo:founder?birthDate }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT xsd:date(?date) WHERE { {?date dbo:deathDate?s. FILTER (?s = res:Muhammad) } }

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?governor WHERE { res:Texas dbp:governor?governor }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT?uri
WHERE {
 ?uri a dbo:MilitaryConflict ;
        dbo:place dbr:San_Antonio ;
        dbo:startDate?date.
  FILTER (?date > "1835-12-31T00:00:00Z"^^xsd:dateTime )
  FILTER (?date <= "1836-12-12T00:00:00Z"^^xsd:dateTime )
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia/>
SELECT DISTINCT?uri WHERE { res:Munch dbo:artist res:The_Scream }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT xsd:date(?date) WHERE { res:De Beers dbo:foundDate?date }

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT?Novelist WHERE {?Novel dbr:title "A Song of Ice and Fire" ; dbp:author?Novelist. }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX dbc: <http://dbpedia.org/resource/Category:]
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT (COUNT(DISTINCT?uri) AS?count)
WHERE {
  {{?uri dbo:country dbr:South_Carolina.
   ?uri rdf:type dbo:River.
  } UNION {
   ?uri dct:subject dbc:Rivers_of_South_Carolina.
  } UNION {
   ?uri dct:subject dbc:Lakes_of_South_Carolina.
  }}
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX dbc: <http://dbpedia.org/resource/Category:]
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT?uri WHERE {
 ?uri dct:subject dbc:States_of_the_United_States ;
    rdf:type dbo:AdministrativeRegion ;
    dbo:populationTotal?area.
  FILTER (?area > 0)
} ORDER BY DESC(?area) LIMIT 1
